{"op":"add","path":"/root","value":"pricing"}
{"op":"add","path":"/elements/pricing","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg","align":"stretch"},"children":["header","billing-picker","plans-grid","selected-alert","comparison","faq"]}}
{"op":"add","path":"/elements/header","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["title","subtitle"]}}
{"op":"add","path":"/elements/title","value":{"type":"Heading","props":{"text":"Plans & Pricing","level":"h1"},"children":[]}}
{"op":"add","path":"/elements/subtitle","value":{"type":"Text","props":{"text":"Start free, upgrade when you're ready. Every plan includes unlimited viewers, 99.9% uptime, and no hidden fees.","variant":"lead"},"children":[]}}
{"op":"add","path":"/elements/billing-picker","value":{"type":"Stack","props":{"direction":"horizontal","gap":"md","align":"center"},"children":["billing-label","billing-options"]}}
{"op":"add","path":"/elements/billing-label","value":{"type":"Text","props":{"text":"Billing period:","variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/billing-options","value":{"type":"RadioGroup","props":{"label":"Billing period","options":["Monthly","Annual — save 20%"],"value":{"$bindState":"/billing"}},"children":[]}}
{"op":"add","path":"/elements/plans-grid","value":{"type":"Grid","props":{"columns":"3","gap":"md"},"repeat":{"statePath":"/plans","key":"id"},"children":["plan-card"]}}
{"op":"add","path":"/elements/plan-card","value":{"type":"Card","props":{"title":{"$item":"name"},"description":{"$item":"tagline"}},"children":["plan-badge","price-heading","price-note","plan-features","spacer","plan-cta"]}}
{"op":"add","path":"/elements/plan-badge","value":{"type":"Badge","props":{"text":"Most popular"},"visible":{"$item":"popular","eq":true},"children":[]}}
{"op":"add","path":"/elements/price-heading","value":{"type":"Heading","props":{"level":"h2","text":{"$cond":{"$state":"/billing","eq":"Annual — save 20%"},"$then":{"$template":"$${priceAnnual}"},"$else":{"$template":"$${priceMonthly}"}}},"children":[]}}
{"op":"add","path":"/elements/price-note","value":{"type":"Text","props":{"variant":"small","text":{"$cond":{"$state":"/billing","eq":"Annual — save 20%"},"$then":{"$item":"annualNote"},"$else":{"$item":"monthlyNote"}}},"children":[]}}
{"op":"add","path":"/elements/plan-features","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm"},"repeat":{"statePath":{"$item":"features"},"key":"id"},"children":["feature-row"]}}
{"op":"add","path":"/elements/feature-row","value":{"type":"Stack","props":{"direction":"horizontal","gap":"sm","align":"start"},"children":["feature-check","feature-text"]}}
{"op":"add","path":"/elements/feature-check","value":{"type":"Text","props":{"text":"✓"},"children":[]}}
{"op":"add","path":"/elements/feature-text","value":{"type":"Text","props":{"text":{"$item":"text"},"variant":"body"},"children":[]}}
{"op":"add","path":"/elements/spacer","value":{"type":"Separator","props":{},"children":[]}}
{"op":"add","path":"/elements/plan-cta","value":{"type":"Button","props":{"label":{"$item":"cta"},"size":"lg","variant":{"$cond":{"$item":"popular","eq":true},"$then":"default","$else":"outline"}},"on":{"press":{"action":"setState","params":{"statePath":"/selectedPlan","value":{"$item":"name"}}}},"children":[]}}
{"op":"add","path":"/elements/selected-alert","value":{"type":"Alert","props":{"title":{"$template":"You picked the ${/selectedPlan} plan!"},"description":"Great choice — complete checkout on the next screen. You can switch plans or cancel anytime."},"visible":{"$state":"/selectedPlan"},"children":[]}}
{"op":"add","path":"/elements/comparison","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["comparison-heading","comparison-table"]}}
{"op":"add","path":"/elements/comparison-heading","value":{"type":"Heading","props":{"text":"Compare plans","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/comparison-table","value":{"type":"Table","props":{"columns":["Feature","Free","Pro","Team"],"caption":"Feature availability across all plans","rows":[["Projects","3","Unlimited","Unlimited"],["Storage","1 GB","50 GB","500 GB"],["Analytics","Basic","Advanced","Advanced + exports"],["Custom domains","—","✓","✓"],["SSO & role management","—","—","✓"],["Audit logs","—","—","✓"],["Support","Community","Priority email","Dedicated manager"]]},"children":[]}}
{"op":"add","path":"/elements/faq","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["faq-heading","faq-accordion"]}}
{"op":"add","path":"/elements/faq-heading","value":{"type":"Heading","props":{"text":"Frequently asked questions","level":"h3"},"children":[]}}
{"op":"add","path":"/elements/faq-accordion","value":{"type":"Accordion","props":{"items":["Can I switch plans later?","What happens when my trial ends?","Do you offer discounts for nonprofits?"]},"children":["faq-1","faq-2","faq-3"]}}
{"op":"add","path":"/elements/faq-1","value":{"type":"Text","props":{"text":"Yes — upgrade, downgrade, or cancel at any time from your billing settings. Changes are prorated automatically.","variant":"body"},"children":[]}}
{"op":"add","path":"/elements/faq-2","value":{"type":"Text","props":{"text":"Your workspace moves to the Free plan. Your data is kept for 90 days, and nothing is deleted unless you choose to remove it.","variant":"body"},"children":[]}}
{"op":"add","path":"/elements/faq-3","value":{"type":"Text","props":{"text":"Yes — registered nonprofits and educational institutions get 40% off Pro and Team. Contact sales with your verification documents.","variant":"body"},"children":[]}}
